// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    LogBook book;

    function setUp() public {
        c = new BANK_SAFE();
        book = new LogBook();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 0, 1e30);

        // Route the log through a real (code-bearing) log contract.
        c.SetLogFile(address(book));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // The deposit must have been recorded in the configured log.
        assertTrue(book.historyCount() == 1);
    }
}

contract LogBook {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        Message memory m;
        m.Sender = _adr;
        m.Time = block.timestamp;
        m.Val = _val;
        m.Data = _data;
        History.push(m);
    }

    function historyCount() public view returns (uint) {
        return History.length;
    }
}
